local UIActivityCommonShopDialog = Class('UIActivityCommonShopDialog')

function UIActivityCommonShopDialog:__init()
    self._shopProductData = {}
end

function UIActivityCommonShopDialog:__delete()
    self._shopProductData = {}
end

function UIActivityCommonShopDialog:Awake()
end
function UIActivityCommonShopDialog:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:Refresh(self._curUuid)
    end))
    return coWait
end
function UIActivityCommonShopDialog:OnFocus(focus)
    if focus then
        if self.topGoods then
            CfUtils.RefreshTopGoods(self.topGoods)
        end
    end
end

function UIActivityCommonShopDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if not argument then return end

        self._curUuid = checkNumber(argument.activityUuid)
        self.activityType = checkInt(argument.customType)
        self.topGoods = checkTable(argument.topGoods)
        self.mallBgImage = checkString(argument.mallBgImage)

        if self.activityType == 0 then
            local activityData = ActivityMgr:GetActivityComponent():GetDojoByActivityId(self._curUuid)
            if not activityData then
                self:FillBg()
                self:FillSelf()
                return
            end
            if activityData.mallBgImage and not string.isEmpty(activityData.mallBgImage) then
                self.mallBgImage = activityData.mallBgImage
            end
            self.activityType = checkInt(activityData.type)
        end

        self:FillBg()
        
        local serverBack = false
        GameUtils.Request(Interfaces.StoreActivityHome, {activityUuid = self._curUuid, activityType = self.activityType}, function(request, response)
            serverBack = true
            if checkNumber(response.errCode) == 0 then
                local jsonData = response.data
                self._shopData =  checkTable(jsonData)
                -- self:StartTimeDown()
            end
        end)   
        
        while not serverBack do
            CoYield()
        end
    end))
    return coWait
end


function UIActivityCommonShopDialog:Refresh(activityUuid)
    self._curUuid = checkNumber(activityUuid)

    self:InitData()
    self:FillSelf()

    self:StartTimeDown()
end

function UIActivityCommonShopDialog:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self:FillTime()
    end, CountDownTime, false, true)
end

function UIActivityCommonShopDialog:InitData()
    local t = self:GetShopData()
    self._shopProductData = checkTable(t.products)
end

function UIActivityCommonShopDialog:FillBg()
    -- print("GetImageFullPath" , ActivityUtils.GetImageFullPath(self.mallBgImage ,false) )
    CfUtils.FillImage(self.ImgBg , ActivityUtils.GetImageFullPath(self.mallBgImage ,false)  )
end

function UIActivityCommonShopDialog:FillSelf()
    self:FillShopInfo()
    self:FillTime()
end
function UIActivityCommonShopDialog:GetShopData()
    return checkTable(self._shopData)
end

function UIActivityCommonShopDialog:FillTime()
    local t = self:GetShopData()
    local time = checkNumber(t.remainingTimes)
    CfUtils.FillText(self.TextTime2, CfUtils.GetTimeHMS(time))
end

function UIActivityCommonShopDialog:FillShopInfo()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(table.count(self._shopProductData), Bind(self, self.OnGetItemByIndex), nil, Bind(self, self.OnGetListItemByIndex))
    else
        self.ScrollView:SetListItemCount(table.count(self._shopProductData))
    end
end

function UIActivityCommonShopDialog:OnGetListItemByIndex(go)
end

function UIActivityCommonShopDialog:OnGetItemByIndex(go, index, row, column)
    if index < 0 then
        return nil
    end
    local data = self._shopProductData[index + 1]

    local scr = CfUtils.GetLuaScr(go, "Game.Activity.Shop.UIActivityCommonShopCellNode")
    if scr then
        scr:Refresh(data, function()
            local isLocked = GroceryUtils.ProductIsLocked(data)
            if isLocked then
                GameUtils.Toast(localize("商品未解锁"))
                return
            end
            local isOnly = GroceryUtils.ProductIsOnly(data)
            if isOnly then
                GameUtils.Toast(localize("商品已拥有"))
                return
            end

            self._curInd = index + 1
            local t = {}
            for k, v in pairs(data.prices) do
                table.insert(t, {
                    current = v.current, 
                    original = v.original,
                    currency = k
                })
            end
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
                goodsId        = data.icon,
                goodsNum       = data.num,
                prices         = t,
                coinPrices     = data.coinPrices,
                maxBuyNum      = data.currentStock,
                rewards        = data.rewards,
                remainTime     = data.refreshTime,
                endTime        = data.nextRefreshLeftSeconds,
                refreshType    = data.refreshType,
                buyCb          = function (price, buyNum)
                    self:OnBuyItem(data.productId, price, buyNum, scr)
                end
            }})
        end)
    end
end

function UIActivityCommonShopDialog:OnBuyItem(productId, price, buyNum, scr)
    local requestPath = Interfaces.StoreActivityBuy

    local data = {
        productId = productId,
        num       = buyNum,
        activityUuid = self._curUuid,
        activityType = self.activityType
    }
    data.currency = price.currency
    GameUtils.Request(requestPath, data, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            if #responseData.rewards > 0 then

                --TODO 统一到DrawRewards,需要修改ActivityGachaponWithoutReplacement里显示皮肤的逻辑
                local skinReward = nil
                for i, v in pairs(responseData.rewards) do
                    local goodsType = GoodsUtils.GetIdType(v.goodsId)
                    if goodsType == Constants.IDType.CardSkin then
                        ---@type CardSkinComponent
                        local cardSkinComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
                        if not cardSkinComponent:IsHasSkin(v.goodsId) then
                            skinReward = v
                            break
                        end
                    end
                end
                
                
                local consumeData = {
                    {goodsId = price.currency, num = price.current * buyNum}
                }
                GoodsUtils.ConsumeGoods(consumeData, true)
                GoodsUtils.DrawRewards(responseData.rewards)

                CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)
                
                if skinReward then
                    UIModule.OpenDialog({ id = Constants.UITypeIds.CommonCardDisplayDialog, parameters = {
                        cardInfo   =  {{ goodsId =  skinReward.goodsId } },
                        isSkin = true       ,
                        onCloseCb  = function()
                            UIModule.CloseDialogById(Constants.UITypeIds.CommonCardDisplayDialog)
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                        end, 
                    } })
                else
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })    
                end
                
                if self._shopProductData[self._curInd] then
                    self._shopProductData[self._curInd].currentStock = checkNumber(self._shopProductData[self._curInd].currentStock) - buyNum
                end

                if scr then
                    scr:RefreshData(self._shopProductData[self._curInd])
                end
            end
        end
    end, function(errStr)
        if string.isEmpty(errStr) or errStr == nil then
            return
        end
        printError("store buy" .. errStr)
    end)
end


